#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> blockSums(max_threads, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const int chunk = (n + T - 1) / T;
        const int start = tid * chunk;
        const int end   = (start + chunk < n) ? (start + chunk) : n;

        long long local = 0;
        for (int i = start; i < end; ++i) {
            local += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(local);
        }
        blockSums[tid] = local;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += blockSums[t];
        }

        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(output[i] + offset);
        }
    }
}
